import {
  runOrdinaryNotificationDispatch,
  type OrdinaryDispatchEnvironment,
} from "../../functions/lib/notifications/ordinary-dispatch.ts";
import sosNotificationWorker from "../sos-notification-delivery/index.ts";
import gpsRelayWorker, { GpsRelayRoom } from "../gps-relay/index.ts";
import { isGpsRelaySocketPath } from "../gps-relay/routing.ts";

export { GpsRelayRoom };

// Generated by `wrangler pages functions build` earlier in the build pipeline.
// Keep the existing Pages Functions router as the HTTP handler; this entrypoint
// adds the GPS WebSocket endpoint and scheduled events without reimplementing
// either routing surface.
// @ts-expect-error This generated module exists after build:worker runs.
import pagesFunctionsWorker from "../../dist/worker/index.js";

type Env = OrdinaryDispatchEnvironment & {
  GPS_ROOMS: DurableObjectNamespace<GpsRelayRoom>;
  GPS_RELAY_E2EE_READY?: string;
};

export default {
  async fetch(request: Request, env: Env, context: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (isGpsRelaySocketPath(url.pathname)) {
      return gpsRelayWorker.fetch(request, env);
    }
    return pagesFunctionsWorker.fetch(request, env, context);
  },

  async scheduled(
    controller: ScheduledController,
    env: Env,
    context: ExecutionContext,
  ): Promise<void> {
    // A single every-minute trigger serves all scheduled SAC jobs.
    context.waitUntil(runOrdinaryNotificationDispatch(env.DB, env, Date.now()));

    // Keep SOS delivery on its every-minute cadence.
    await sosNotificationWorker.scheduled(
      { ...controller, cron: "* * * * *" },
      env,
      context,
    );

    // Run retention cleanup once per hour, on the top-of-hour invocation.
    if (new Date(controller.scheduledTime).getUTCMinutes() === 0) {
      await sosNotificationWorker.scheduled(
        { ...controller, cron: "0 * * * *" },
        env,
        context,
      );
    }
  },
};
